<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();$products=$p->query("SELECT * FROM products ORDER BY name")->fetchAll();$calc=null;
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$p->prepare("SELECT * FROM products WHERE id=?");$s->execute([$_POST['product_id']]);$pr=$s->fetch();$base=(float)$pr['cost']+(float)$pr['labor_cost']+(float)$pr['packaging_cost'];$loss=$base*((float)$pr['loss_pct']/100);$cost=$base+$loss;$tax=(float)setting('tax_pct','0')/100;$card=(float)setting('card_fee_pct','0')/100;$margin=(float)$pr['desired_margin']/100;$den=1-$tax-$card-$margin;$suggested=$den>0?$cost/$den:$cost*1.5;$calc=compact('pr','base','loss','cost','suggested');}
page_head('Precificação automática');?>
<div class="grid g2"><div class="card"><h2>Calcular preço</h2><form method="post"><?=csrf_field()?><label>Produto</label><select name="product_id"><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><button class="primary">Calcular</button></form><p>Considera custo, mão de obra, embalagem, perdas, impostos, taxa de cartão e margem desejada.</p></div>
<?php if($calc):?><div class="card"><h2><?=e($calc['pr']['name'])?></h2><p>Custo base: <b><?=money($calc['base'])?></b></p><p>Perdas: <b><?=money($calc['loss'])?></b></p><p>Custo completo: <b><?=money($calc['cost'])?></b></p><p>Preço atual: <b><?=money($calc['pr']['price'])?></b></p><p class="total">Preço recomendado: <?=money($calc['suggested'])?></p></div><?php endif;?></div><?php page_foot();?>